import { MakeLogicType, actions, afterMount, connect, kea, listeners, path } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'
import { lemonToast } from 'lib/lemon-ui/LemonToast/LemonToast'
import { deleteWithUndo } from 'lib/utils/deleteWithUndo'
import { databaseTableListLogic } from 'scenes/data-management/database/databaseTableListLogic'

import { DataWarehouseViewLink } from '~/types'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface joinsDataLogicValues {
    joins: DataWarehouseViewLink[]
    joinsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface joinsDataLogicActions {
    refreshDatabaseSchema: () => {
        value: true
    } // databaseTableListLogic
    deleteJoin: (join: DataWarehouseViewLink) => {
        join: DataWarehouseViewLink
    }
    loadJoins: () => any
    loadJoinsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadJoinsSuccess: (
        joins: DataWarehouseViewLink[],
        payload?: any
    ) => {
        joins: DataWarehouseViewLink[]
        payload?: any
    }
}

export type joinsDataLogicType = MakeLogicType<joinsDataLogicValues, joinsDataLogicActions>

export const joinsDataLogic = kea<joinsDataLogicType>([
    path(['products', 'dataWarehouse', 'joinsDataLogic']),
    connect({ actions: [databaseTableListLogic, ['refreshDatabaseSchema']] }),
    actions({ deleteJoin: (join: DataWarehouseViewLink) => ({ join }) }),
    loaders({
        joins: [
            [] as DataWarehouseViewLink[],
            { loadJoins: async () => (await api.dataWarehouseViewLinks.list()).results },
        ],
    }),
    listeners(({ actions }) => ({
        deleteJoin: ({ join }): void => {
            void deleteWithUndo({
                endpoint: api.dataWarehouseViewLinks.determineDeleteEndpoint(),
                object: { id: join.id, name: `${join.field_name} on ${join.source_table_name}` },
                callback: () => {
                    actions.refreshDatabaseSchema()
                    actions.loadJoins()
                },
            }).catch((e) => {
                lemonToast.error(`Failed to delete warehouse view link: ${e.detail}`)
            })
        },
    })),
    afterMount(({ actions }) => {
        actions.loadJoins()
    }),
])
